1340	// success; otherwise { ok: false, reason } with reason 'uncloneable' (the
1341	// value cannot be structured-cloned at all — `error` carries the raw clone
1342	// failure for callers that propagate it) or 'sharedMemory' (the clone
1343	// succeeded but retains shared bytes).
1344	function independentCopy(value) {
1345	  let cloned;
1346	  try {
1347	    cloned = structuredClone(value);
1348	  } catch (error) {
1349	    return { ok: false, reason: 'uncloneable', error };
1350	  }
1351	  if (containsSharedMemory(cloned)) {
1352	    return { ok: false, reason: 'sharedMemory' };
1353	  }
1354	  return { ok: true, copy: cloned };
1355	}
1356	
1357	// Receives the caller's run input: put it through independentCopy, the same
1358	// clone-then-judge rule every other saved value (configured message/result,
1359	// business or compensation return) already follows. The run input is promised
1360	// to every node — and to every business attempt and compensation snapshot —
1361	// as an independent copy, and a SharedArrayBuffer cannot satisfy that
1362	// promise: cloning it (or a typed array / DataView backed by one) "succeeds"
1363	// while the clone keeps sharing the underlying bytes with the object the
1364	// caller holds, so a business action that rewrites its input copy could
1365	// mutate the caller's data, and a failed attempt's rewrite would leak into
1366	// the next attempt and later retries. An input whose clone actually retains
1367	// shared memory is therefore rejected before any node can run — a TypeError
1368	// (the synchronous entry throws it; the asynchronous entry rejects with the
1369	// same error) explaining that the run input contains shared memory and
1370	// independent copies cannot be guaranteed. An input that cannot be cloned at
1371	// all keeps the raw structuredClone failure, as before.
1372	const RUN_INPUT_SHARED_MEMORY_MESSAGE = 'run input contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this run cannot be started';
1373	
1374	function cloneRunInput(input) {
1375	  const copy = independentCopy(input);
1376	  if (!copy.ok) {
1377	    if (copy.reason === 'uncloneable') throw copy.error;
1378	    throw new TypeError(RUN_INPUT_SHARED_MEMORY_MESSAGE);
1379	  }
1380	  return copy.copy;
1381	}
1382	
1383	// Builds the independent input copy handed to a single business attempt or
1384	// stored (and later handed, again copied, to compensation) at an action's
1385	// success moment.
1386	//
1387	// A plain structuredClone is almost that copy, but it cannot carry a default
1388	// a successful form adds onto a host object during the run: forms apply
1389	// defaults as ordinary own properties on the live run input, so the input
1390	// itself and the following conditions see them at once, but structuredClone
1391	// reproduces a Date (and every other clone-special node — RegExp, Map/Set own
1392	// properties, byte views, Errors apart from "cause", boxed primitives) from
1393	// its internal value alone and silently drops every attached own property.
1394	// The business action's argument copy, the compensation snapshot and each
1395	// compensation attempt's copy therefore lost exactly the run-time form
1396	// defaults, while plain-object defaults kept working.
1397	//
1398	// Receiver-time handling is unchanged: cloneRunInput already discarded the
1399	// own properties the CALLER attached to such an object before the run, and
1400	// forms only ever add properties (never remove another form's survivors), so
1401	// within a run every own property of a live node that is missing from its
1402	// structured-clone counterpart is precisely a subtree a successful form
1403	// created there — primitive defaults at the leaves and fresh plain-object
1404	// parents along the path. This walks the live graph and its clone in
1405	// lockstep, reattaches an independent copy of each such dropped subtree, and
1406	// otherwise leaves the clone exactly as structuredClone produced it:
1407	//  - the Date keeps its original type and time value, the default merely
1408	//    joins it as an own property;
1409	//  - the whole multi-level path a default created is reattached together;
1410	//  - identity the clone preserved is kept — when two input fields point at
1411	//    one Date, both still point at the single reattached clone node inside
1412	//    this copy (each invocation gets its own copy, so retries and the live
1413	//    run input stay independent of one another);
1414	//  - a reattached subtree is itself structured-cloned, so an action or
1415	//    compensation editing a default, a created parent or the Date itself
1416	//    cannot reach the run input, the caller's input or any other copy.
1417	//
1418	// One reachability gap the enumerable-key walk cannot cover on its own: a
1419	// native Error's own "cause" survives the clone (message/name/stack are
1420	// copied as primitives; every other own property is dropped) but is
1421	// non-enumerable on both the source and the clone, so Object.keys never
1422	// visits it and a Date reachable only through one or more causes would lose
1423	// its run-time defaults here. Mirroring the native-error branch of
1424	// containsSharedMemory, the walk pairs source and clone causes explicitly —
1425	// a cause chain (Error -> cause -> Error -> cause -> Date) is followed link
1426	// by link exactly like any other path.
1427	//
1428	// A second Error-slot gap the key walk cannot repair on its own is "message"
1429	// (and, by the same mechanism, "name"). structuredClone serializes an Error's
1430	// message slot through ABSTRACT STRING COERCION of the live value: a live own
1431	// message holding an object (the object a successful form creates when a
1432	// default lands at failure.message.label), a number or a boolean (a form
1433	// default written directly at failure.message) is cloned as the coerced text
1434	// "[object Object]", "5" or "false" — and the clone even installs that text
1435	// as a fresh own property, so the clone never LACKS "message" the way it
1436	// lacks a non-string "name" (which the clone drops outright, letting the
1437	// ordinary dropped-key reattachment handle it). The form-written value and
1438	// its already-validated fields would therefore reach a business action as a
1439	// plain string.
1440	//
1441	// Coercion itself can also THROW. "toString" is an ordinary data field here,
1442	// exactly like "label": a string default written at failure.message.toString
1443	// leaves the message object with an own non-callable toString. When the
1444	// serializer asks that object to coerce itself to the message string, no
1445	// conversion path works (an own "toString" that is not a function is ignored
1446	// and the inherited valueOf yields a non-primitive), so the whole
1447	// structuredClone fails with "Cannot convert object to primitive value" —
1448	// before the business operation or compensation was ever entered, the async
1449	// run died while merely preparing its argument copy. The same crash reaches
1450	// "name" and every Error nested through enumerable properties or a cause
1451	// chain. copyInputWithFormDefaults therefore masks every own non-string
1452	// message/name data slot for the duration of that one clone (message with "",
1453	// which the serializer installs as the slot's own string; name with
1454	// undefined, which makes the serializer omit it) and restores the live slots
1455	// immediately after, so the clone skeleton is built — aliases, cycles, causes
1456	// and all — without ever coercing a form-written slot. restoreErrorMessage
1457	// then repairs the message slot exactly as before, in the same
1458	// standalone-clone manner the key walk reattaches any other subtree a clone
1459	// dropped: such a message subtree holds only form-created plain objects and
1460	// primitive defaults (an own non-callable "toString" being just one more
1461	// string field among them), so one structuredClone is its complete,
1462	// independent deep copy (there is no nested clone-special node the clone
1463	// graph could pair or alias through it). A masked non-string "name" is simply
1464	// absent on the fresh clone and is reattached by the ordinary dropped-key
1465	// walk below, with the same standalone-clone isolation.
1466	function restoreErrorMessage(source, target) {
1467	  // Only a live OWN data property that is not a string can be a form-written
1468	  // value: a form defines defaults as own enumerable data properties, and the
1469	  // field types it accepts are string/number/integer/boolean, so a repair is
1470	  // needed exactly for an own non-string. Everything else — an absent or
1471	  // deleted own message (the prototype's "" slot), an inherited message, an
1472	  // accessor (forms never install one; the clone reads it through its slot),
1473	  // and an ordinary string message — is left exactly as structuredClone
1474	  // produced it, so existing string messages keep their current behavior.
1475	  // (The slot-masking pass guarantees the target currently carries only the
1476	  // mask "" whenever this branch is taken, regardless of how the live value
1477	  // would otherwise have coerced.)
1478	  let descriptor;
1479	  try {
1480	    descriptor = Object.getOwnPropertyDescriptor(source, 'message');
1481	  } catch {
1482	    return;
1483	  }
1484	  if (!descriptor || !('value' in descriptor)) return;
1485	  const liveMessage = descriptor.value;
1486	  if (liveMessage === undefined || typeof liveMessage === 'string') return;
1487	
1488	  // Replace the clone's coerced text with an independent deep copy of the
1489	  // true form-written value. Form-created message subtrees hold only
1490	  // primitives and fresh plain objects, so this clone always succeeds; cloning
1491	  // here detaches the repaired slot from the live run input so an action
1492	  // rewriting the message, one of its fields or a created parent cannot reach
1493	  // the run input, the caller's Error or another attempt copy. Define an own
1494	  // enumerable data property (the shape the live own message has) rather than
1495	  // assigning, so no inherited accessor can intercept the repair.
1496	  Object.defineProperty(target, 'message', {
1497	    value: structuredClone(liveMessage),
1498	    writable: true, enumerable: true, configurable: true,
1499	  });
1500	}
