6	// through an Error's "cause". Forms apply defaults on the live run input, so
7	// context.input and later conditions always saw them; but the independent
8	// copies handed to business actions and compensations are rebuilt from a
9	// structured clone, and the reattachment walk followed only enumerable own
10	// properties — an Error's cause is non-enumerable, so every default under it
11	// was silently lost in those copies. These tests pin the fix: defaults under
12	// cause chains (cause is the Date itself, a plain object holding the Date, or
13	// another Error whose cause continues the chain) reach every copy, the Date
14	// keeps its type and time, the Error keeps its message and cause content,
15	// aliases stay aliases within one copy, and every copy stays independent of
16	// the run input, the caller's input and every other copy.
17	
18	const WHEN = Date.parse('2024-01-02T03:04:05.000Z');
19	
20	// start -> form-one (adds defaults onto the Date inside failure's cause)
21	//       -> act (business + compensation in async runs; a message in sync)
22	//       -> check (condition reading the defaults through the cause)
23	//       -> seen / missed (two ends)
24	function causeDefaultWorkflow(actNode, extraFormFields = []) {
25	  return {
26	    id: 'error-cause-form-defaults',
27	    entry: 'start',
28	    nodes: [
29	      { id: 'start', type: 'trigger', next: 'form-one' },
30	      { id: 'form-one', type: 'form', next: 'act', schema: { fields: [
31	        // A default landing directly on the Date inside the Error's cause.
32	        { path: 'failure.cause.createdAt.channel', type: 'string', default: 'web' },
33	        // A multi-level path whose parents are created on that Date.
34	        { path: 'failure.cause.createdAt.meta.source', type: 'string', default: 'form' },
35	        ...extraFormFields,
36	      ] } },
37	      actNode,
38	      {
39	        id: 'check', type: 'condition', then: 'seen', else: 'missed',
40	        condition: { all: [
41	          { field: 'failure.cause.createdAt.channel', operator: 'eq', value: 'web' },
42	          { field: 'failure.cause.createdAt.meta.source', operator: 'eq', value: 'form' },
43	        ] },
44	      },
45	      { id: 'seen', type: 'end', result: 'default-visible' },
46	      { id: 'missed', type: 'end', result: 'default-missing' },
47	    ],
48	  };
49	}
50	
51	// The failure Error carries a non-enumerable cause holding the Date; a second
52	// input field aliases the same Date from outside the cause chain.
53	function callerInput() {
54	  const createdAt = new Date(WHEN);
55	  const failure = new Error('boom', { cause: { createdAt } });
56	  return { failure, note: { at: createdAt } };
57	}
