61	  assert.equal(input.failure.message, 'boom', 'the Error keeps its message');
62	  const { createdAt } = input.failure.cause;
63	  assert.ok(createdAt instanceof Date, 'the cause Date stays a Date');
64	  assert.equal(createdAt.getTime(), WHEN, 'the Date keeps its time value');
65	  assert.equal(createdAt.channel, 'web');
66	  assert.deepEqual(createdAt.meta, { source: 'form' });
67	}
