1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { executeWorkflowAsync } from '../src/engine.js';
4	
5	const UNREADABLE = '无法读取异常信息';
6	
7	function linearWorkflow(actionProps = {}) {
8	  return {
9	    id: 'ops',
10	    entry: 'start',
11	    nodes: [
12	      { id: 'start', type: 'trigger', next: 'prep' },
13	      { id: 'prep', type: 'action', message: 'prepared', next: 'work' },
14	      { id: 'work', type: 'action', ...actionProps, next: 'done' },
15	      { id: 'done', type: 'end', result: 'finished' },
16	    ],
17	  };
18	}
19	
20	function revokedProxy() {
21	  const { proxy, revoke } = Proxy.revocable({}, {});
22	  revoke();
23	  return proxy;
24	}
25	
26	test('a thrown revoked Proxy fails the attempt with the fixed unreadable-error text', async () => {
27	  let calls = 0;
28	  const execution = await executeWorkflowAsync(linearWorkflow({ operation: 'charge' }), {}, {
29	    charge: () => { calls += 1; throw revokedProxy(); },
30	  });
31	  assert.equal(calls, 1);
32	  assert.equal(execution.status, 'action_failed');
33	  assert.equal(execution.nodeId, 'work');
34	  assert.equal(execution.attempts, 1);
35	  assert.equal(execution.error, UNREADABLE);
36	  assert.deepEqual(execution.actionAttempts, [
37	    { nodeId: 'work', attempt: 1, ok: false, error: UNREADABLE, nextDelayMs: 0 },
38	  ]);
39	  // Prior successful output and the trace survive; the failed node stores
40	  // nothing and its successor never runs.
41	  assert.deepEqual(execution.context.output, { prep: 'prepared' });
42	  assert.deepEqual(execution.trace.map(n => n.nodeId), ['start', 'prep', 'work']);
43	});
44	
45	test('a Promise rejected with a revoked Proxy is handled exactly like a throw', async () => {
46	  let calls = 0;
47	  const execution = await executeWorkflowAsync(linearWorkflow({ operation: 'charge' }), {}, {
48	    charge: () => { calls += 1; return Promise.reject(revokedProxy()); },
49	  });
50	  assert.equal(calls, 1);
51	  assert.equal(execution.status, 'action_failed');
52	  assert.equal(execution.error, UNREADABLE);
53	  assert.deepEqual(execution.actionAttempts, [
54	    { nodeId: 'work', attempt: 1, ok: false, error: UNREADABLE, nextDelayMs: 0 },
55	  ]);
56	});
57	
58	test('a proxy whose prototype read throws also yields the fixed text', async () => {
59	  const hostile = new Proxy({}, { getPrototypeOf() { throw new Error('trap boom'); } });
60	  const execution = await executeWorkflowAsync(linearWorkflow({ operation: 'charge' }), {}, {
61	    charge: () => { throw hostile; },
62	  });
63	  assert.equal(execution.status, 'action_failed');
64	  assert.equal(execution.error, UNREADABLE);
65	  assert.deepEqual(execution.actionAttempts.map(a => a.error), [UNREADABLE]);
66	});
67	
68	test('hostile exception values respect the node retry config: one record per actual invocation', async () => {
69	  let calls = 0;
