function tag(value, seen = new Set()) {
  if (value === null) return 'null';
  const t = typeof value;
  if (t === 'number') return `n:${String(value)}`;
  if (t === 'boolean') return `b:${value}`;
  if (t === 'string') return `s:${JSON.stringify(value)}`;
  if (t === 'undefined') return 'u';
  if (t !== 'object') return t;
  if (seen.has(value)) return '<cycle>';
  seen.add(value);
  if (value instanceof Error) return `Err(${value.constructor.name}){msg:${tag(value.message,seen)},cause:${Object.hasOwn(value,'cause')?tag(value.cause,seen):'-'},keys:${JSON.stringify(Object.keys(value))}}`;
  if (Array.isArray(value)) return `[${value.map(v=>tag(v,seen)).join(',')}]`;
  if (value instanceof Date) return `Date(${value.getTime()}){${Object.keys(value).map(k=>k+':'+tag(value[k],seen)).join(',')}}`;
  let ks; try { ks = Object.keys(value); } catch { return '<?>' }
  return `{${ks.map(k=>{let v;try{v=value[k]}catch{v='<throw>'}return k+':'+tag(v,seen)}).join(',')}}`;
}
async function run(engine, fields) {
